contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint which) public payable {
        require(address(this).balance >= amount);

        uint balBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();

        bool reverted;

        if (which % 3 == 0) {
            try c.withdraw(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (which % 3 == 1) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.sendMoney(address(this), amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        c.fallback{value: amount}();

        assert(reverted && address(c).balance == balBefore + amount && c.depositsCount() == depositsBefore + 1);
    }

    receive() external payable {}
}

