contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, uint value, uint withdrawValue) public payable {
        require(address(this).balance >= value);

        address owner = c.owner();
        uint balanceBefore = address(c).balance;

        bool revertedWithdrawAll;
        bool revertedWithdraw;
        bool revertedSendMoney;

        if (msg.sender != owner) {
            try c.withdrawAll() {
                revertedWithdrawAll = false;
            } catch {
                revertedWithdrawAll = true;
            }
            try c.withdraw(withdrawValue) {
                revertedWithdraw = false;
            } catch {
                revertedWithdraw = true;
            }
            try c.sendMoney(target, value) {
                revertedSendMoney = false;
            } catch {
                revertedSendMoney = true;
            }
            assert(
                revertedWithdrawAll &&
                revertedWithdraw &&
                revertedSendMoney &&
                address(c).balance == balanceBefore
            );
        } else {
            c.withdraw(withdrawValue);
            assert(address(c).balance == balanceBefore - withdrawValue);
        }
    }

    receive() external payable {}
}

