        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        assert(
            c.depositsCount() == afterDepositCount &&
            address(c).balance <= afterDepositBalance &&
            address(c).balance + address(this).balance >= afterDepositBalance
        );
    }

